type ActionType = 'create' | 'update' | 'delete';

function handleAction(action: ActionType, data: any): string {
  switch (action) {
    case 'create': return `Created: ${JSON.stringify(data)}`;
    case 'update': return `Updated: ${JSON.stringify(data)}`;
    case 'delete': return `Deleted: ${data.id}`;
    default: throw new Error(`Unknown action: ${action}`);
  }
}
